// app/router.tsx — TanStack Router instance for SSR
//
// Replaces the code-based `routeTree.tsx` (which was a Vite SPA workaround).
// The file-based route tree under src/app/routes/ is auto-generated by
// @tanstack/router-plugin (see vite.config.ts).
import { createRouter as createTanstackRouter } from "@tanstack/react-router";
import { routeTree } from "./routeTree.gen";
import { setupRouterSsrQueryIntegration } from "@tanstack/react-router-with-query";
import {
  QueryClient,
  QueryClientProvider,
} from "@tanstack/react-query";
import { ConvexProvider, ConvexReactClient } from "convex/react";

// Convex client (lazy — only set up if env is present)
const convexUrl = import.meta.env.VITE_CONVEX_URL as string | undefined;
const convex = convexUrl ? new ConvexReactClient(convexUrl) : null;

// TanStack Query client (server-cache for the SSR pass)
const queryClient = new QueryClient();

export function createRouter() {
  const router = createTanstackRouter({
    routeTree,
    context: { queryClient, convex },
    defaultPreload: "intent",
    // Wire Convex + Query into the SSR pass
    Wrap: ({ children }) => (
      <ConvexProvider client={convex ?? new ConvexReactClient("http://localhost:0")}>
        <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
      </ConvexProvider>
    ),
  });
  setupRouterSsrQueryIntegration({ router, queryClient });
  return router;
}

declare module "@tanstack/react-router" {
  interface Register {
    router: ReturnType<typeof createRouter>;
  }
}
